function icsText(t) {
  const d = function (x) { return new Date(x).toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, ""); };
  return ["BEGIN:VCALENDAR", "VERSION:2.0", "PRODID:-//The Nail Bawse//Webinar//EN", "BEGIN:VEVENT", "UID:" + t + "-webinar@thenailbawse.com", "DTSTAMP:" + d(Date.now()), "DTSTART:" + d(t), "DTEND:" + d(t + DUR), "SUMMARY:Build Your AI Agent — The Nail Bawse (free live class on Zoom)", "LOCATION:" + ZOOM, "DESCRIPTION:Join on Zoom: " + ZOOM, "URL:" + ZOOM, "END:VEVENT", "END:VCALENDAR"].join("\r\n");
}
async function register(request, env) {
  let f; try { f = await request.formData(); } catch (e) { return html(webinarPage("Something went wrong. Please try again."), 400, env); }
  if (String(f.get("website") || "").trim()) return Response.redirect("https://" + APEX + "/webinar", 303);
  const name = String(f.get("first_name") || "").trim().slice(0, 80);
  const email = String(f.get("email") || "").trim().toLowerCase().slice(0, 200);
  const optin = f.get("marketing_opt_in") ? 1 : 0;
  if (!name || !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return html(webinarPage("Please enter your first name and a valid email address."), 400, env);
  const next = nextSession(Date.now());
  await env.DB.prepare("INSERT INTO signups (created_at, source, first_name, email, marketing_opt_in, session_start_utc, user_agent) VALUES (?, ?, ?, ?, ?, ?, ?) ON CONFLICT(source, email, session_start_utc) DO UPDATE SET first_name = excluded.first_name, marketing_opt_in = MAX(marketing_opt_in, excluded.marketing_opt_in)").bind(new Date().toISOString(), "webinar", name, email, optin, next ? new Date(next).toISOString() : "tba", String(request.headers.get("user-agent") || "").slice(0, 300)).run();
  let body;
  if (next) {
    const ics = "data:text/calendar;charset=utf-8," + encodeURIComponent(icsText(next));
    body = '<section class="page-hero"><div class="container"><p class="eyebrow"><span class="eyebrow-line"></span> YOU’RE REGISTERED</p><h1>You’re in, <em>' + esc(name) + '.</em></h1><p class="lede">Build Your AI Agent — free live on Zoom with Anisia Burroughs.</p><p style="font:normal 30px/1.3 var(--serif);margin:0 0 30px">' + esc(fmt(next)) + '</p><div class="btn-row"><a class="button button--primary" href="' + ics + '" download="the-nail-bawse-webinar.ics">Add to my calendar <span aria-hidden="true">→</span></a><a class="text-link" href="' + ZOOM + '" target="_blank" rel="noopener noreferrer">Zoom join link <span aria-hidden="true">→</span></a></div><p class="note">Add it to your calendar now — the invite includes your Zoom link. The link opens at session time.</p></div></section>';
  } else {
    body = '<section class="page-hero"><div class="container"><p class="eyebrow"><span class="eyebrow-line"></span> YOU’RE ON THE LIST</p><h1>Thank you, <em>' + esc(name) + '.</em></h1><p class="lede">The next session date will be announced soon.</p></div></section>';
  }
  return html(page("You’re registered | The Nail Bawse™", "Webinar registration confirmed.", "/webinar", body), 200, env);
}
export default {
  async fetch(request, env) {
    const url = new URL(request.url);
    if (url.hostname === "www." + APEX) { url.hostname = APEX; return Response.redirect(url.toString(), 301); }
    let path; try { path = decodeURIComponent(url.pathname); } catch (e) { path = url.pathname; }
    const key = path.replace(/\/+$/, "").toLowerCase() || "/";
    const fr = await funnel(request, env, { key: key, path: path, nextSession: nextSession, icsText: icsText, ZOOM: ZOOM, APEX: APEX, DUR: DUR }); if (fr) return fr;
    if (key === "/webinar" && request.method === "POST") return register(request, env);
    if (request.method !== "GET" && request.method !== "HEAD") return new Response("Method not allowed", { status: 405 });
    if (key === "/shop") return html(shopPage(), 200, env);
    if (key === "/webinar") return html(webinarPage(""), 200, env);
    if (key === "/monthly" || key === "/community") return html(clubPage(key), 200, env);
    if (key === "/resources") return html(resourcesPage(), 200, env);
    if (path === "/" || path === "/index.html") return respond("/index.html", 200, env);
    if (FILES[path]) return respond(path, 200, env);
    if (FILES[path + ".html"]) return respond(path + ".html", 200, env);
    if (path.endsWith("/") && FILES[path.slice(0, -1) + ".html"]) return respond(path.slice(0, -1) + ".html", 200, env);
    return respond("/404.html", 404, env);
  }
};
